"""Maintenance-owned expansion models; historical documents remain nullable."""
from sqlalchemy import MetaData,Table,Column,String,DateTime,CheckConstraint,Index,text
from sqlalchemy.dialects.postgresql import JSONB
metadata=MetaData(schema='maintenance')
orders=Table('orders',metadata,Column('id',String(40),primary_key=True),Column('tenant_id',String(40),nullable=False),Column('organization_context',JSONB),CheckConstraint("organization_context is null or jsonb_typeof(organization_context)='object'",name='ck_cc16_orders_organization_context'),Index('ix_cc16_orders_division','tenant_id',text("(organization_context->>'division_ref_id')")))
assignments=Table('assignments',metadata,Column('id',String(40),primary_key=True),Column('tenant_id',String(40),nullable=False),Column('worker_context_snapshot',JSONB),CheckConstraint("worker_context_snapshot is null or jsonb_typeof(worker_context_snapshot)='object'",name='ck_cc16_assignments_worker_context_snapshot'))
time_entries=Table('time_entries',metadata,Column('id',String(40),primary_key=True),Column('tenant_id',String(40),nullable=False),Column('worker_ref_id',String(40),nullable=False),Column('started_at',DateTime(timezone=True),nullable=False),Column('ended_at',DateTime(timezone=True),nullable=False),Column('organization_context',JSONB),Column('labor_cost_snapshot',JSONB),CheckConstraint("organization_context is null or jsonb_typeof(organization_context)='object'",name='ck_cc16_time_entries_organization_context'),CheckConstraint("labor_cost_snapshot is null or jsonb_typeof(labor_cost_snapshot)='object'",name='ck_cc16_time_entries_labor_cost_snapshot'),Index('ix_cc16_time_worker_interval','tenant_id','worker_ref_id','started_at','ended_at'))
